// Generated by AI (UnitTest MCP)
//! Structural regression coverage for Bridge's capability-aware static navigation.

const CONTEXT: &str = include_str!("../static/context.html");
const EVIDENCE: &str = include_str!("../static/evidence.html");
const FLEET: &str = include_str!("../static/index.html");
const KNOWLEDGE: &str = include_str!("../static/knowledge.html");
const TELEMETRY: &str = include_str!("../static/telemetry.html");

const EXPECTED_NAVIGATION: &str = "<navclass=\"nav\"aria-label=\"Industrialsurfaces\"><ahref=\"/\">Fleet</a><ahref=\"/evidence\">Evidence</a><ahref=\"/telemetry\">Telemetry</a><ahref=\"/context\">Context</a><ahref=\"/knowledge\">Knowledge</a><aaria-disabled=\"true\">Work</a><aaria-disabled=\"true\">Design</a><aaria-disabled=\"true\">Constitution</a><aaria-disabled=\"true\">Administration</a></nav>";

#[test]
fn static_pages_share_one_capability_aware_navigation_contract() {
    for (page, source) in [
        ("Fleet", FLEET),
        ("Evidence", EVIDENCE),
        ("Telemetry", TELEMETRY),
        ("Context", CONTEXT),
        ("Knowledge", KNOWLEDGE),
    ] {
        assert_eq!(
            normalize_navigation(source),
            EXPECTED_NAVIGATION,
            "{page} navigation drifted from the Bridge capability contract"
        );
        for capability in [
            "Fleet",
            "Evidence",
            "Telemetry",
            "Context",
            "Knowledge",
            "Work",
            "Design",
            "Constitution",
            "Administration",
        ] {
            assert!(
                navigation(source).contains(capability),
                "{page} navigation must expose {capability}"
            );
        }
    }
}

#[test]
fn evidence_related_record_links_remain_separate_from_navigation() {
    for id in ["work-api", "constitution-api", "knowledge-api"] {
        assert!(
            EVIDENCE.contains(&format!("id=\"{id}\"")),
            "Evidence must retain its related-record link {id}"
        );
    }
    for removed_navigation_id in ["work-link", "constitution-link", "knowledge-link"] {
        assert!(
            !EVIDENCE.contains(&format!("id=\"{removed_navigation_id}\"")),
            "Evidence navigation must not rewire a capability placeholder through raw API links"
        );
    }
}

fn normalize_navigation(source: &str) -> String {
    navigation(source)
        .replace("aria-current=\"page\"", "")
        .split_whitespace()
        .collect()
}

fn navigation(source: &str) -> &str {
    let start = source
        .find("<nav class=\"nav\" aria-label=\"Industrial surfaces\">")
        .expect("Bridge page has a navigation element");
    let end = source[start..]
        .find("</nav>")
        .map(|offset| start + offset + "</nav>".len())
        .expect("Bridge navigation closes");
    &source[start..end]
}
